const cfg = $('Set config: keywords & filters').first().json;
const kws = String(cfg.keywords || '').split(',').map((s) => s.trim()).filter(Boolean);
const cutoff = Math.floor((Date.now() - (Number(cfg.hoursBack) || 48) * 3600 * 1000) / 1000);
const minPts = Number(cfg.minPoints) || 0;
// Algolia HN search: recent stories matching the keyword, above a points floor
return kws.map((keyword) => ({ json: {
  keyword,
  feedUrl: 'https://hn.algolia.com/api/v1/search_by_date?query=' + encodeURIComponent(keyword) +
    '&tags=story&hitsPerPage=30&numericFilters=' + encodeURIComponent('created_at_i>' + cutoff + ',points>=' + minPts),
} }));

const src = $('Expand keyword searches').all();
const kwOf = (it, idx) => {
  let pi = it.pairedItem; let p = (typeof pi === 'number') ? pi : (Array.isArray(pi) ? (pi[0] || {}).item : (pi || {}).item);
  if (p === undefined || p === null) p = idx;
  return (src[p] && src[p].json.keyword) || '';
};
const seen = new Set(); const items = [];
const responses = $input.all();
for (let idx = 0; idx < responses.length; idx++) {
  let j = responses[idx].json;
  // HTTP node returns parsed JSON (object) for application/json, or a string we must parse
  if (typeof j === 'string') { try { j = JSON.parse(j); } catch (e) { j = {}; } }
  if (j && typeof j.data === 'string') { try { j = JSON.parse(j.data); } catch (e) {} }
  const hits = (j && j.hits) || [];
  const keyword = kwOf(responses[idx], idx);
  for (const h of hits) {
    if (seen.has(h.objectID)) continue;
    seen.add(h.objectID);
    const title = h.title || h.story_title || '';
    if (!title) continue;
    items.push({
      title,
      url: h.url || ('https://news.ycombinator.com/item?id=' + h.objectID),
      hn: 'https://news.ycombinator.com/item?id=' + h.objectID,
      points: h.points || 0, comments: h.num_comments || 0, author: h.author || '',
      keyword, ts: (h.created_at_i || 0) * 1000,
    });
  }
}
items.sort((x, y) => y.points - x.points);
const capped = items.slice(0, 40).map((a, i) => ({ i, ...a }));
return [{ json: { items: capped, count: capped.length } }];

const cfg = $('Set config: keywords & filters').first().json;
const items = $json.items || [];
const schema = { type: 'object', additionalProperties: false, required: ['picks'], properties: {
  picks: { type: 'array', items: { type: 'object', additionalProperties: false,
    required: ['i', 'keyword', 'headline', 'why', 'importance'], properties: {
      i: { type: 'integer' }, keyword: { type: 'string' }, headline: { type: 'string' },
      why: { type: 'string' }, importance: { type: 'integer' } } } } } };
const system = 'You monitor Hacker News for ONE reader. Each story is tagged with the keyword it matched and carries points and comment counts. Drop off-topic matches and low-signal noise, then pick what this reader would actually want. For each pick: keyword = keep the tag, headline = tight rewrite, why = one sentence on why it matters to this reader (a launch, a tool, a hiring signal, a thread to join), importance = 0-100 (weigh relevance and traction). Be terse.';
const user = 'READER CONTEXT: ' + cfg.context + '\n\nPick the top ' + (cfg.topN || 15) + '.\n\nSTORIES (reference each by index i):\n' +
  items.map((a) => '[' + a.i + '] {' + a.keyword + '} ' + a.title + ' — ' + a.points + ' pts, ' + a.comments + ' comments').join('\n');
return [{ json: { body: {
  model: cfg.model, max_tokens: 2000, system,
  messages: [{ role: 'user', content: user }],
  output_config: { format: { type: 'json_schema', schema } },
} } }];

const cfg = $('Set config: keywords & filters').first().json;
const items = $('Parse & tag HN stories').first().json.items || [];
const top = Number(cfg.topN) || 15;
const blocks = ($json.content || []);
const text = (blocks.find((b) => b.type === 'text') || {}).text || '{"picks":[]}';
let picks = []; try { picks = (JSON.parse(text).picks) || []; } catch (e) {}
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
picks = picks.map((p) => ({ ...p, ...(items[p.i] || {}), keyword: p.keyword || (items[p.i] || {}).keyword }))
  .filter((p) => p.url).sort((a, b) => b.importance - a.importance).slice(0, top);
const rows = picks.map((p) =>
  '<li style="margin:9px 0"><a href="' + esc(p.url) + '" style="font-weight:700">' + esc(p.headline) + '</a> ' +
  '<span style="color:#999">· ' + p.points + ' pts · <a href="' + esc(p.hn) + '" style="color:#999">' + p.comments + ' comments</a> · #' + esc(p.keyword) + '</span><br>' +
  '<span style="color:#333">' + esc(p.why) + '</span></li>').join('');
const html = '<h2 style="font-family:system-ui,Arial">Hacker News monitor</h2>' +
  '<ul style="font-family:system-ui,Arial;padding-left:18px">' + rows + '</ul>' +
  '<p style="color:#999;font-size:12px">' + picks.length + ' picks from ' + items.length + ' matched stories · ' + esc(cfg.model) + '</p>';
const subject = picks.length ? 'HN monitor: ' + picks.length + ' picks · top ' + (picks[0] ? picks[0].points + ' pts' : '') : 'HN monitor: nothing matched';
return [{ json: { subject, html, count: picks.length } }];
